import unittest
from candidate import vowels_count

class TestVowelsCount(unittest.TestCase):
    def test_vowels_count_empty_string(self):
        self.assertEqual(vowels_count(""), 0)

    def test_vowels_count_single_vowel(self):
        self.assertEqual(vowels_count("a"), 1)

    def test_vowels_count_multiple_vowels(self):
        self.assertEqual(vowels_count("aeiou"), 5)

    def test_vowels_count_single_y_at_end(self):
        self.assertEqual(vowels_count("abcdey"), 2)

    def test_vowels_count_single_Y_at_end(self):
        self.assertEqual(vowels_count("ABCDEY"), 2)

    def test_vowels_count_no_vowels(self):
        self.assertEqual(vowels_count("bcdfghjklmnpqrstvwxyz"), 0)

    def test_vowels_count_mixed_case(self):
        self.assertEqual(vowels_count("AeIoUy"), 5)

    def test_vowels_count_none_input(self):
        with self.assertRaises(TypeError):
            vowels_count(None)

    def test_vowels_count_non_string_input(self):
        with self.assertRaises(TypeError):
            vowels_count(123)

    def test_vowels_count_whitespace_input(self):
        self.assertEqual(vowels_count("   "), 0)

if __name__ == '__main__':
    unittest.main()
